mapper.select:
WITH requested_scenes AS ( SELECT DISTINCT vb.scene_id FROM shots sh JOIN shot_sequences ss ON ss.id = sh.sequence_id JOIN visual_beats vb ON vb.id = ss.visual_beat_id JOIN scenes s ON s.id = vb.scene_id WHERE s.project_id = #{projectId} AND sh.id IN
#{shotId}
), ordered AS ( SELECT sh.id AS shot_id, vb.scene_id, LAG(sh.id) OVER scene_order AS previous_shot_id, LAG(sh.end_state_json::text) OVER scene_order AS previous_end_state_json FROM shots sh JOIN shot_sequences ss ON ss.id = sh.sequence_id JOIN visual_beats vb ON vb.id = ss.visual_beat_id WHERE vb.scene_id IN (SELECT scene_id FROM requested_scenes) WINDOW scene_order AS ( PARTITION BY vb.scene_id ORDER BY vb.order_index, ss.order_index, sh.order_index ) ) SELECT o.shot_id, pl.id AS location_id, pl.name, pl.description, pl.visual_prompt, o.previous_shot_id, o.previous_end_state_json FROM ordered o JOIN scenes s ON s.id = o.scene_id LEFT JOIN project_locations pl ON pl.id = s.project_location_id AND pl.project_id = s.project_id WHERE o.shot_id IN
#{shotId}
ORDER BY o.shot_id
